import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { Button, MoneyInput, Slideout, dispatchAppToast } from '@linm-soft-org/linm-web-common-components';
import { useAppDispatch } from '../../store/hooks';
import { apiClient, unwrap, type BffResponse } from '../../services/api';
import type {
  CashVoucherCompanyAllocationDto,
  CompanyAllocationMethod,
  SaveCashVoucherCompanyAllocationDto,
} from '../../services/kt/models';
import { formatMoneyVnd } from '../../utils/formatters';
import { getApiErrorMessage } from '../../utils/getApiErrorMessage';
import styles from '../../styles/documentForm.module.css';

export type CompanyAllocateConfirmPayload = SaveCashVoucherCompanyAllocationDto;

export type CompanyAllocateSlideoutProps = {
  isOpen: boolean;
  onClose: () => void;
  voucherTotal: number;
  initialMethod?: CompanyAllocationMethod | string;
  initialLines?: CashVoucherCompanyAllocationDto[];
  onConfirm: (payload: CompanyAllocateConfirmPayload) => void | Promise<void>;
  testIdPrefix: string;
  saving?: boolean;
  readOnly?: boolean;
};

type CompanyRow = {
  code: string;
  name: string;
  selected: boolean;
  amount: number;
  ratio: number;
};

type ActiveCompanyApiItem = {
  id: string;
  code?: string;
  name: string;
  shortName?: string;
};

const METHOD_OPTIONS: { value: CompanyAllocationMethod; label: string }[] = [
  { value: 'Manual', label: 'Nhập đích danh' },
  { value: 'Equal', label: 'Phân bổ bình quân' },
  { value: 'Ratio', label: 'Phân bổ tỷ lệ' },
];

function normalizeMethod(raw: string | undefined | null): CompanyAllocationMethod {
  const m = (raw ?? '').trim();
  if (m === 'Manual' || m.toLowerCase() === 'manual') return 'Manual';
  if (m === 'Ratio' || m.toLowerCase() === 'ratio') return 'Ratio';
  if (m === 'Equal' || m.toLowerCase() === 'Equal') return 'Equal';
  return 'Equal';
}

const ROUND_TOLERANCE = 1;

function round0(n: number): number {
  return Math.round(n);
}

async function fetchActiveCompanies(): Promise<{ code: string; name: string }[]> {
  const byCode = new Map<string, { code: string; name: string }>();
  try {
    const res = await apiClient.get<BffResponse<ActiveCompanyApiItem[]>>('/companies/active-list');
    for (const item of unwrap(res) ?? []) {
      const code = (item.code || item.id || '').trim();
      if (!code) continue;
      byCode.set(code.toUpperCase(), {
        code,
        name: (item.name || item.shortName || code).trim(),
      });
    }
  } catch {
    // empty — slideout shows empty state
  }
  return [...byCode.values()].sort((a, b) => a.code.localeCompare(b.code, 'vi'));
}

function applyEqual(rows: CompanyRow[], total: number): CompanyRow[] {
  const selected = rows.filter(r => r.selected);
  if (selected.length === 0) return rows;
  const n = selected.length;
  const base = Math.floor(total / n);
  let allocated = 0;
  const amounts = new Map<string, { amount: number; ratio: number }>();
  selected.forEach((r, i) => {
    const amount = i === n - 1 ? total - allocated : base;
    if (i < n - 1) allocated += amount;
    const ratio = total > 0 ? Math.round((amount * 10000) / total) / 100 : 0;
    amounts.set(r.code.toUpperCase(), { amount, ratio });
  });
  return rows.map(r => {
    if (!r.selected) return { ...r, amount: 0, ratio: 0 };
    const calc = amounts.get(r.code.toUpperCase());
    return calc ? { ...r, amount: calc.amount, ratio: calc.ratio } : r;
  });
}

function applyRatio(rows: CompanyRow[], total: number): CompanyRow[] {
  const selected = rows.filter(r => r.selected);
  if (selected.length === 0) return rows;
  const weightSum = selected.reduce((s, r) => s + (Number(r.ratio) || 0), 0);
  if (weightSum <= 0) return rows;
  let allocated = 0;
  const amounts = new Map<string, number>();
  selected.forEach((r, i) => {
    let amount: number;
    if (i === selected.length - 1) {
      amount = total - allocated;
    } else {
      amount = round0((total * (Number(r.ratio) || 0)) / weightSum);
      allocated += amount;
    }
    amounts.set(r.code.toUpperCase(), amount);
  });
  return rows.map(r => {
    if (!r.selected) return { ...r, amount: 0 };
    const amount = amounts.get(r.code.toUpperCase()) ?? 0;
    const pct = weightSum > 0
      ? Math.round(((Number(r.ratio) || 0) * 10000) / weightSum) / 100
      : 0;
    return { ...r, amount, ratio: pct };
  });
}

export const CompanyAllocateSlideout: React.FC<CompanyAllocateSlideoutProps> = ({
  isOpen,
  onClose,
  voucherTotal,
  initialMethod = 'Equal',
  initialLines,
  onConfirm,
  testIdPrefix,
  saving = false,
  readOnly = false,
}) => {
  const dispatch = useAppDispatch();
  const [loading, setLoading] = useState(false);
  const [method, setMethod] = useState<CompanyAllocationMethod>('Equal');
  const [rows, setRows] = useState<CompanyRow[]>([]);
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    if (!isOpen) return;
    let cancelled = false;
    setLoading(true);
    const initMethod = normalizeMethod(initialMethod);
    setMethod(initMethod);

    void (async () => {
      try {
        const companies = await fetchActiveCompanies();
        if (cancelled) return;
        const initialByCode = new Map(
          (initialLines ?? []).map(l => [l.targetCompanyCode.toUpperCase(), l]),
        );
        let next: CompanyRow[] = companies.map(c => {
          const prev = initialByCode.get(c.code.toUpperCase());
          return {
            code: c.code,
            name: prev?.targetCompanyName || c.name,
            selected: !!prev,
            amount: prev ? Number(prev.amount) || 0 : 0,
            ratio: prev ? Number(prev.ratio) || 0 : 0,
          };
        });
        // Include any saved codes not in active list
        for (const line of initialLines ?? []) {
          const key = line.targetCompanyCode.toUpperCase();
          if (!next.some(r => r.code.toUpperCase() === key)) {
            next.push({
              code: line.targetCompanyCode,
              name: line.targetCompanyName || line.targetCompanyCode,
              selected: true,
              amount: Number(line.amount) || 0,
              ratio: Number(line.ratio) || 0,
            });
          }
        }
        if (initMethod === 'Equal' && next.some(r => r.selected)) {
          next = applyEqual(next, round0(voucherTotal));
        } else if (initMethod === 'Ratio' && next.some(r => r.selected)) {
          next = applyRatio(next, round0(voucherTotal));
        }
        setRows(next);
      } catch (e: unknown) {
        if (!cancelled) {
          dispatchAppToast(dispatch, {
            message: getApiErrorMessage(e, 'Không tải được danh sách đơn vị cơ sở.'),
            type: 'error',
          });
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();

    return () => { cancelled = true; };
  }, [isOpen, initialMethod, initialLines, voucherTotal, dispatch]);

  const selectedTotal = useMemo(
    () => rows.filter(r => r.selected).reduce((s, r) => s + (Number(r.amount) || 0), 0),
    [rows],
  );

  const totalRounded = round0(voucherTotal);
  const diff = selectedTotal - totalRounded;

  const recompute = useCallback((nextMethod: CompanyAllocationMethod, nextRows: CompanyRow[]) => {
    if (nextMethod === 'Equal') return applyEqual(nextRows, totalRounded);
    if (nextMethod === 'Ratio') return applyRatio(nextRows, totalRounded);
    return nextRows;
  }, [totalRounded]);

  const handleMethodChange = (next: CompanyAllocationMethod) => {
    setMethod(next);
    setRows(prev => recompute(next, prev));
  };

  const handleSelectAll = (checked: boolean) => {
    setRows(prev => {
      const next = prev.map(r => ({ ...r, selected: checked, amount: checked ? r.amount : 0, ratio: checked ? r.ratio : 0 }));
      return recompute(method, next);
    });
  };

  const handleConfirm = async () => {
    const selected = rows.filter(r => r.selected);
    if (selected.length === 0) {
      dispatchAppToast(dispatch, {
        message: 'Chọn ít nhất một đơn vị cơ sở để phân bổ.',
        type: 'warning',
      });
      return;
    }
    if (totalRounded <= 0) {
      dispatchAppToast(dispatch, {
        message: 'Tổng tiền phiếu chưa hợp lệ — không thể phân bổ.',
        type: 'error',
      });
      return;
    }
    if (method === 'Manual' && Math.abs(diff) > ROUND_TOLERANCE) {
      dispatchAppToast(dispatch, {
        message: `Tổng phân bổ (${formatMoneyVnd(selectedTotal)}) phải khớp tổng phiếu (${formatMoneyVnd(totalRounded)}).`,
        type: 'error',
      });
      return;
    }
    if (method === 'Ratio') {
      const weightSum = selected.reduce((s, r) => s + (Number(r.ratio) || 0), 0);
      if (weightSum <= 0) {
        dispatchAppToast(dispatch, {
          message: 'Nhập tỷ lệ lớn hơn 0 cho các đơn vị đã chọn.',
          type: 'error',
        });
        return;
      }
    }

    const payload: CompanyAllocateConfirmPayload = {
      method,
      lines: selected.map((r, i) => ({
        targetCompanyCode: r.code,
        targetCompanyName: r.name,
        amount: Number(r.amount) || 0,
        ratio: Number(r.ratio) || 0,
        sortOrder: i,
      })),
    };

    setSubmitting(true);
    try {
      await onConfirm(payload);
      onClose();
    } catch (e: unknown) {
      dispatchAppToast(dispatch, {
        message: getApiErrorMessage(e, 'Không lưu được phân bổ.'),
        type: 'error',
      });
    } finally {
      setSubmitting(false);
    }
  };

  const allSelected = rows.length > 0 && rows.every(r => r.selected);
  const busy = loading || saving || submitting;

  const footer = (
    <div className={styles.modalActions}>
      <Button variant="secondary" onClick={onClose} data-testid={`${testIdPrefix}-company-allocate-cancel`}>
        {readOnly ? 'Đóng' : 'Hủy'}
      </Button>
      {!readOnly && (
        <Button
          variant="primary"
          onClick={() => void handleConfirm()}
          disabled={busy || rows.length === 0 || totalRounded <= 0}
          data-testid={`${testIdPrefix}-company-allocate-confirm`}
        >
          {busy ? 'Đang lưu…' : 'Xác nhận phân bổ'}
        </Button>
      )}
    </div>
  );

  return (
    <Slideout
      isOpen={isOpen}
      onClose={onClose}
      title="Phân bổ theo đơn vị cơ sở"
      width="min(920px, 94vw)"
      customFooter={footer}
      data-testid={`${testIdPrefix}-company-allocate-slideout`}
    >
      {loading ? (
        <p data-testid={`${testIdPrefix}-company-allocate-loading`}>Đang tải…</p>
      ) : rows.length === 0 ? (
        <p data-testid={`${testIdPrefix}-company-allocate-empty`}>Không có đơn vị cơ sở khả dụng.</p>
      ) : (
        <>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 16, marginBottom: 12, alignItems: 'center' }}>
            <div>
              <label className={styles.label} htmlFor={`${testIdPrefix}-company-allocate-method`}>
                Hình thức phân bổ
              </label>
              <select
                id={`${testIdPrefix}-company-allocate-method`}
                data-testid={`${testIdPrefix}-company-allocate-method`}
                value={method}
                disabled={readOnly}
                onChange={e => handleMethodChange(e.target.value as CompanyAllocationMethod)}
                style={{ minWidth: 200, marginLeft: 8 }}
              >
                {METHOD_OPTIONS.map(o => (
                  <option key={o.value} value={o.value}>{o.label}</option>
                ))}
              </select>
            </div>
            <div data-testid={`${testIdPrefix}-company-allocate-voucher-total`}>
              Tổng phiếu: <strong>{formatMoneyVnd(totalRounded)}</strong>
            </div>
            <div data-testid={`${testIdPrefix}-company-allocate-sum`}>
              Tổng phân bổ: <strong>{formatMoneyVnd(selectedTotal)}</strong>
              {Math.abs(diff) > 0 && (
                <span style={{ marginLeft: 8, color: Math.abs(diff) > ROUND_TOLERANCE ? '#b91c1c' : '#64748b' }}>
                  (lệch {formatMoneyVnd(diff)})
                </span>
              )}
            </div>
          </div>

          <div className={styles.tableWrapper}>
            <table className={styles.linesTable}>
              <thead>
                <tr>
                  <th>
                    {!readOnly && (
                      <input
                        type="checkbox"
                        checked={allSelected}
                        data-testid={`${testIdPrefix}-company-allocate-select-all`}
                        onChange={e => handleSelectAll(e.target.checked)}
                        title="Chọn tất cả"
                      />
                    )}
                  </th>
                  <th>Mã ĐVCS</th>
                  <th>Tên đơn vị</th>
                  {method === 'Ratio' && <th>Tỷ lệ</th>}
                  <th>Số tiền</th>
                </tr>
              </thead>
              <tbody>
                {rows.map((row, idx) => (
                  <tr key={row.code} data-testid={`${testIdPrefix}-company-allocate-row-${idx}`}>
                    <td>
                      <input
                        type="checkbox"
                        checked={row.selected}
                        disabled={readOnly}
                        data-testid={`${testIdPrefix}-company-allocate-select-${idx}`}
                        onChange={e => {
                          const checked = e.target.checked;
                          setRows(prev => {
                            const next = prev.map((r, i) => (i === idx
                              ? { ...r, selected: checked, amount: checked ? r.amount : 0, ratio: checked ? r.ratio : 0 }
                              : r));
                            return recompute(method, next);
                          });
                        }}
                      />
                    </td>
                    <td>{row.code}</td>
                    <td>{row.name}</td>
                    {method === 'Ratio' && (
                      <td>
                        <MoneyInput
                          value={row.ratio}
                          disabled={readOnly || !row.selected}
                          data-testid={`${testIdPrefix}-company-allocate-ratio-${idx}`}
                          onChange={ratio => {
                            setRows(prev => {
                              const next = prev.map((r, i) => (i === idx ? { ...r, ratio } : r));
                              return recompute(method, next);
                            });
                          }}
                        />
                      </td>
                    )}
                    <td>
                      <MoneyInput
                        value={row.amount}
                        disabled={readOnly || !row.selected || method !== 'Manual'}
                        data-testid={`${testIdPrefix}-company-allocate-amount-${idx}`}
                        onChange={amount => {
                          setRows(prev => prev.map((r, i) => (i === idx ? { ...r, amount } : r)));
                        }}
                      />
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </>
      )}
    </Slideout>
  );
};
